# Thủy mặc tập 7: Tốt Động, Chúc Động 1426 (mã tm7), bản 4 theo mẫu tm5
S=[
('hook1',"Nếu biết trước ám hiệu tấn công của một đạo quân đông gấp nhiều lần mình, bạn sẽ làm gì với bí mật ấy?"),
('hook2',"Năm ấy, nghĩa quân Lam Sơn đã chọn một cách lạ: họ nằm im. Không một tiếng động, không một bóng người, giữa một vùng ruộng lầy."),
('hook3',"Mấy vạn quân nhà Minh cứ thế bước vào. Trận ấy là Tốt Động, Chúc Động, và hai viên quan lớn của nhà Minh đã phải trả giá bằng chính mạng mình."),
('hook4',"Vì sao im lặng lại thắng được đạo quân đông như thế? Có hai thứ làm nên chuyện ấy: mấy tên do thám bị bắt, và một tiếng súng hiệu."),
('goc_re',"Năm một nghìn bốn trăm linh bảy, nhà Minh chiếm nước ta. Mười một năm sau, Lê Lợi dựng cờ khởi nghĩa ở Lam Sơn, Thanh Hóa."),
('goc_re',"Những năm đầu, nghĩa quân nhiều lần bị vây và phải rút lên núi. Đến năm một nghìn bốn trăm hai mươi sáu, họ đã làm chủ từ Nghệ An trở vào."),
('goc_re',"Một cánh quân nhỏ do Lý Triện, Đỗ Bí chỉ huy tiến sát thành Đông Quan, tức Thăng Long. Thấy nguy, nhà Minh sai Vương Thông đem thêm năm vạn quân."),
('the_nguy',"Có quân đông trong tay, Vương Thông chia ba đường, tràn ra khỏi thành Đông Quan để đè bẹp cánh quân nhỏ của Lý Triện."),
('the_nguy',"Lý Triện giả thua, kéo giặc qua cầu Tam La vào ruộng lầy rồi quay lại đánh. Nhưng quân nhà Minh quá đông, lại dựng hàng rào chông tre chặn lại."),
('diem_thap',"Voi chiến của nghĩa quân giẫm phải chông, quay đầu chạy loạn. Nhìn lúc ấy, cánh quân nhỏ của Lý Triện tưởng như sắp bị nghiền nát."),
('buoc_ngoat',"Đinh Lễ và Nguyễn Xí đem ba nghìn quân cùng hai con voi tới cứu, mà vẫn ít hơn giặc nhiều lần."),
('buoc_ngoat',"Đúng lúc ấy, nghĩa quân bắt được mấy tên do thám của giặc. Từ miệng chúng, kế hoạch của Vương Thông lộ ra hết."),
('buoc_ngoat',"Quân chính của giặc sẽ vượt sông đánh thẳng vào, còn một cánh khác lén vòng ra sau lưng nghĩa quân."),
('buoc_ngoat',"Ám hiệu là tiếng súng: hễ súng nổ, tất cả cùng xông vào. Thứ đầu tiên là thế, bí mật của giặc đã nằm trong tay Lam Sơn."),
('lan1',"Biết trước tiếng súng sẽ là hiệu lệnh, Đinh Lễ và Lý Triện chọn điều ngược lại: không một tiếng động nào được phát ra."),
('lan1',"Nghĩa quân phục sẵn ở Tốt Động và Chúc Động, hai làng nằm ven cánh đồng lầy, rồi nằm im chờ. Thứ hai là chính sự im lặng ấy."),
('lang',"Quân nhà Minh đi tới. Không nghe súng nổ, không thấy bóng người, họ cho rằng quanh đó không có quân Lam Sơn, liền đi tắt cho nhanh."),
('lang',"Con đường tắt dẫn thẳng vào giữa ruộng lầy. Đội quân đông đảo dàn dài ra trong bùn, càng đi càng xa thành, chung quanh vẫn im phăng phắc."),
('cao_trao',"Rồi phục binh ập ra từ hai làng. Quân nhà Minh bị kẹp giữa, dồn chạy về phía sông, người chết đuối không đếm xuể."),
('cao_trao',"Sử ta chép giặc chết và bị bắt mấy vạn người. Sử nhà Minh chép ít hơn, nhưng cũng nhận hai, ba vạn người chết."),
('chi_tiet_nguoi',"Hai viên quan lớn của nhà Minh là Trần Hiệp và Lý Lượng chết giữa trận. Vương Thông bị thương, cùng tàn quân chạy ngược về thành Đông Quan."),
('don_cuoi',"Nghe tin thắng lớn, Lê Lợi kéo đại quân từ Nghệ An ra bắc, vây chặt thành Đông Quan."),
('ket',"Vương Thông sang để giữ đất cho nhà Minh, rốt cuộc lại bị nhốt ngay trong tòa thành mình phải giữ."),
('ket',"Một tiếng súng hiệu không bao giờ nổ đã đưa mấy vạn quân nhà Minh vào ruộng lầy Tốt Động. Cảm ơn bạn đã lắng nghe câu chuyện này."),
]
